from PIL import Image
R=Path(__file__).resolve().parents[1]
def write(p,s): (R/p).write_text(s,encoding='utf-8')
def img(n,alt,cls='',eager=False):
 k=f'factory-111A{n}' if isinstance(n,int) else n
 dimensions=Image.open(R/f"assets/media/{k}-1600.webp").size
 return f'<img class="{cls}" src="assets/media/{k}-1600.webp" srcset="assets/media/{k}-640.webp 640w, assets/media/{k}-1600.webp 1600w" sizes="(max-width: 700px) 100vw, 60vw" width="{dimensions[0]}" height="{dimensions[1]}" alt="{alt}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def label(t):return f'<p class="eyebrow">{t}</p>'
def btn(t,url,outline=False):return f'<a class="button {"outline" if outline else ""}" href="{url}">{t}<span aria-hidden="true">↗</span></a>'
def split(k,title,body,n,alt,extra='',dark=False):return f'<section class="section {"navy" if dark else ""}"><div class="container split"><div class="image-frame reveal">{img(n,alt)}</div><div class="reveal">{label(k)}<h2>{title}</h2><p>{body}</p>{extra}</div></div></section>'
def cta():return '<section class="cta section"><div class="container"><div>'+label('LET’S BUILD SOMETHING BETTER')+'<h2>Your product.<br>Our next packaging project.</h2></div>'+btn('Discuss your requirements','quotation.html')+'</div></section>'
